import os
import pathlib

if os.name == 'nt':
    versioned_tfelhome="TFELHOME_5.1.0".replace(".", "_").replace("-", "_")
    if versioned_tfelhome in os.environ:
        tfelhome = os.environ[versioned_tfelhome]
    elif "TFELHOME" in os.environ:
        tfelhome = os.environ["TFELHOME"]
    else:
        # remove bin\python...\site_packages\tfel\material\__init__.py
        tfelhome = pathlib.Path(*pathlib.Path(__file__).parts[0:-6])
        os.environ["TFELHOME"] = str(tfelhome)
    # Only add DLL directory if it exists (handles conda environments)
    bin_dir = pathlib.Path(str(tfelhome)) / 'bin'
    if bin_dir.exists():
        os.add_dll_directory(str(bin_dir))

from ._material import *

